#include <iostream>
#include <string>

int main() {
    std::string input_str, output_str;
    std::cin >> input_str;
    output_str += input_str.front();
    int marker = -1;
    for (size_t index = 1; index < input_str.size(); ++index) {
        if (input_str[index] == 'a' && index + 1 < input_str.size() && input_str[index + 1] == 't' && marker == -1) {
            marker = 1;
            output_str += '@';
            ++index;
        } else if (input_str[index] == 'd' && index + 2 < input_str.size() && input_str[index + 1] == 'o' && input_str[index + 2] == 't' && index + 2 != input_str.size() - 1) {
            output_str += '.';
            index += 2;
        } else {
            output_str += input_str[index];
        }
    }
    for (size_t i = 0; i < output_str.size(); ++i) {
        std::cout << output_str[i];
    }
    return 0;
}
